# Now run the component analysis with proper padding
height, width = len(grid), len(grid[0])
visited = [[False]*width for _ in range(height)]

def find_component(r, c):
    """Find all cells in the connected component of color grid[r][c]"""
    color = grid[r][c]
    result = []
    stack = [(r, c)]
    visited[r][c] = True

    while stack:
        cr, cc = stack.pop()
        result.append((cr, cc))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr+dr, cc+dc
            if 0 <= nr < height and 0 <= nc < width and not visited[nr][nc]:
                if grid[nr][nc] == color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    return result, color

# Find all unique connected components
from collections import defaultdict
color_to_components = defaultdict(list)  # color -> list of components

visited_all = [[False]*width for _ in range(height)]
for r in range(height):
    for c in range(width):
        if not visited_all[r][c]:
            cells, color = find_component(r, c)
            color_to_components[color].append(cells)
            for cell in cells:
                visited_all[cell[0]][cell[1]] = True

print(f"Components per color:")
for color in sorted(color_to_components.keys()):
    comps = color_to_components[color]
    total_cells = sum(len(c) for c in comps)
    print(f"  Color {color}: {len(comps)} components, {total_cells} total cells")

# For each component, check if it has "holes" (background pixels completely surrounded)
def find_holes_in_component(component_cells, grid):
    """Find all 8s inside the bounding box of a component that are 'trapped'"""
    height, width = len(grid), len(grid[0])

    # Get bounding box
    r_min, r_max = min(r for r,c in component_cells), max(r for r,c in component_cells)
    c_min, c_max = min(c for r,c in component_cells), max(c for r,c in component_cells)

    trapped_8s = set()

    # BFS from edge of bounding box to find all reachable 8s
    queue = [(r, c) for r in range(r_min, r_max+1) for c in range(c_min, c_max+1) 
              if grid[r][c] == 8]

    trapped = set()

    for start_r, start_c in queue:
        # Check if this 8 is adjacent to anything outside the bounding box
        is_boundary = False
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = start_r + dr, start_c + dc
            if nr < r_min or nr > r_max or nc < c_min or nc > c_max:
                is_boundary = True
                break

        if is_boundary:
            continue  # Not trapped

        # Add to BFS
        trapped.add((start_r, start_c))

        stack = [(start_r, start_c)]
        while stack:
            sr, sc = stack.pop()

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = sr+dr, sc+dc

                # Must be 8 and within bounding box and not yet visited
                if 0 <= nr < height and 0 <= nc < width:
                    if grid[nr][nc] == 8 and (nr, nc) not in trapped:
                        # Check if adjacent to boundary
                        adj_boundary = False
                        for ddr, ddc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nmr, nmc = nr+ddr, nc+ddc
                            if nmr < r_min or nmr > r_max or nmc < c_min or nmc > c_max:
                                adj_boundary = True
                                break

                        if not adj_boundary:
                            trapped.add((nr, nc))
                            stack.append((nr, nc))

    return trapped

output = [row[:] for row in grid]

filled_total = 0
for color, components in color_to_components.items():
    if color == 8:
        continue  # Don't modify 8s themselves

    for component_cells in components:
        trapped = find_holes_in_component(component_cells, grid)
        if trapped:
            for r, c in trapped:
                output[r][c] = color
            filled_total += len(trapped)
            print(f"Filled {len(trapped)} trapped 8s for color {color}")

print(f"\nTotal holes filled: {filled_total}")
print("\nOutput grid:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(map(str, row))}")

# Submit answer
{"action": "submit", "grid": output}

