def get_row_hash(row):
    # Normalize row by tracking only colors and their runs
    runs = []
    if len(row) == 0:
        return ""

    i = 0
    while i < len(row):
        val = row[i]
        run_len = 1
        while i + run_len < len(row) and row[i + run_len] == val:
            run_len += 1
        runs.append(val)
        i += run_len
    return tuple(runs)

